import{B as e,Q as t,s as n,z as r}from"./chunks/framework.hue4hZNP.js";import"./chunks/admin-injury-types.BL0ti9kN.js";import"./chunks/dashboard-rankings.Cfy4uZDk.js";import"./chunks/admin-gm-dashboard.BDLefZxA.js";import"./chunks/player-effective-stats.Cvvw4wU4.js";var i=JSON.parse(`{"title":"Grow a Wrestler","description":"","frontmatter":{},"headers":[],"relativePath":"guide/grow-a-wrestler.md","filePath":"guide/grow-a-wrestler.md"}`),a={name:`guide/grow-a-wrestler.md`};function o(n,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[e(`<h1 id="grow-a-wrestler" tabindex="-1">Grow a Wrestler <a class="header-anchor" href="#grow-a-wrestler" aria-label="Permalink to &quot;Grow a Wrestler&quot;">​</a></h1><p>A booker&#39;s guide to the long game: fans, tiers, momentum, wear &amp; tear, injuries, and contracts. Everything that makes a wrestler&#39;s career a story instead of a number.</p><p><strong>The growth loop:</strong> wrestlers perform on shows → they gain (or lose) <strong>fans</strong> → fans drive their <strong>tier</strong> and their <strong>salary</strong> → matches cost <strong>condition</strong> → injuries and age bite → book wisely to keep stars healthy and rising.</p><hr><h2 id="fans-and-tiers" tabindex="-1">Fans and tiers <a class="header-anchor" href="#fans-and-tiers" aria-label="Permalink to &quot;Fans and tiers&quot;">​</a></h2><p>Fans are the currency of fame. Wrestlers gain them by:</p><ul><li><strong>Winning matches</strong> — more for main-event wins, most for decisive wins over popular opponents.</li><li><strong>Retaining or winning championships</strong> — titleholders gain fans on every successful defense.</li><li><strong>Winning tournaments</strong> and headline moments.</li></ul><p>Fans per wrestler are tracked <strong>per universe</strong>, so the same wrestler can be a legend in one universe and a rookie in another. Every show start snapshots each wrestler&#39;s fan count for the season&#39;s historical record.</p><p>Tiers rank the roster from <strong>Rookie</strong> up through <strong>Icon</strong>. Tier gates championship prestige — a title&#39;s tier only considers wrestlers at or above it — and drives the rankings ladder contenders climb toward title shots.</p><p><img src="/screenshots/dashboard-rankings.png" alt="Wrestler rankings"></p><hr><h2 id="health-momentum-and-status-cards" tabindex="-1">Health, momentum, and status cards <a class="header-anchor" href="#health-momentum-and-status-cards" aria-label="Permalink to &quot;Health, momentum, and status cards&quot;">​</a></h2><p>Each wrestler carries live combat stats shown (with all modifiers applied) on their profile and the Player Dashboard:</p><ul><li><strong>Health</strong> — the pool that matches and bumps deplete. A hurt wrestler performs worse and risks injury.</li><li><strong>Stamina</strong> — spent by match length and stipulations; recovered between shows.</li><li><strong>Momentum</strong> — the hot-streak meter. Winners ride it, losers lose it — momentum swings make underdog runs possible.</li><li><strong>Effective stats</strong> — hover any stat to see the full breakdown: campaign bonuses, injuries, bumps, and active Status Cards. Green badges are positive, red are negative.</li></ul><p><img src="/screenshots/player-effective-stats.png" alt="Effective stats and status cards"></p><hr><h2 id="wear-tear" tabindex="-1">Wear &amp; tear <a class="header-anchor" href="#wear-tear" aria-label="Permalink to &quot;Wear &amp; tear&quot;">​</a></h2><p>Matches leave a mark. <strong>Physical condition</strong> degrades every match based on:</p><ul><li><strong>Match intensity</strong> — Extreme rules double the wear.</li><li><strong>Positioning</strong> — main events demand more than openers.</li></ul><p>Low condition means health penalties in the ring and, at the extreme, <strong>forced retirement</strong>. Condition recovers slowly on its own; booking a worn-down star every week is how you lose them. Admins can toggle the whole wear-and-tear system under <strong>Admin → Game Settings</strong>.</p><hr><h2 id="injuries" tabindex="-1">Injuries <a class="header-anchor" href="#injuries" aria-label="Permalink to &quot;Injuries&quot;">​</a></h2><p>Big hits and brutal stipulations can injure a wrestler:</p><ul><li>Injuries carry a <strong>severity</strong> with a health penalty and a <strong>recovery time</strong> — the wrestler is sidelined or weakened until healed.</li><li>Severity types are admin-configurable under <strong>Admin → Injury Management</strong> (name, severity, recovery days).</li><li>Players speed recovery with <strong>Recovery</strong> backstage actions; bookers just have to wait — or avoid the hardcore match with their top star the week after a cage.</li></ul><p><img src="/screenshots/admin-injury-types.png" alt="Injury management"></p><hr><h2 id="backstage-actions" tabindex="-1">Backstage actions <a class="header-anchor" href="#backstage-actions" aria-label="Permalink to &quot;Backstage actions&quot;">​</a></h2><p>Player-controlled wrestlers can take one <strong>backstage action</strong> per day:</p><ul><li><strong>Training</strong> — push stats upward.</li><li><strong>Recovery</strong> — heal faster from injuries and condition damage.</li><li><strong>Promo</strong> — build hype (and heat with rivals) without getting physical.</li></ul><p>Choices matter — the action spends the day, so a wrestler training can&#39;t simultaneously recover.</p><hr><h2 id="contracts-and-the-cost-of-fame" tabindex="-1">Contracts and the cost of fame <a class="header-anchor" href="#contracts-and-the-cost-of-fame" aria-label="Permalink to &quot;Contracts and the cost of fame&quot;">​</a></h2><p>Salaries are <strong>dynamically tied to fan count</strong> — a rising star costs more every month they rise. The GM Dashboard surfaces budget, roster health, and locker-room morale so you can see the bill coming.</p><p>The strategic tension: you must invest in developing new talent to afford keeping the superstars you built. Let a veteran&#39;s fans stagnate and their contract stays cheap; push a prospect to the main event and budget for their raise.</p><p><img src="/screenshots/admin-gm-dashboard.png" alt="GM Dashboard"></p><hr><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><a href="./schedule-a-show.html">Schedule a Show</a> — where all this growth happens.</li><li><a href="./manage-rivalries.html">Manage Rivalries</a> — heat that turns winners into stars.</li><li><a href="./run-a-season.html">Run a Season</a> — the yearly frame around the grind.</li><li>The auto-generated <a href="./wrestler-profile.html">Wrestler Profile</a> guide documents every profile screen.</li></ul>`,38)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};